<?php require_once __DIR__.'/../includes/auth.php';require_post();csrf_check();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id){flash('error','Invalid product.');redirect('index.php');}$s=$pdo->prepare('SELECT COUNT(*) FROM sale_items WHERE product_id=?');$s->execute([$id]);if($s->fetchColumn()>0){flash('error','This product has sales history and cannot be deleted. Set its stock to zero or keep it for records.');redirect('index.php');}$pdo->beginTransaction();try{$s=$pdo->prepare('DELETE FROM stock_movements WHERE product_id=?');$s->execute([$id]);$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([$id]);$pdo->commit();flash('success','Product deleted.');}catch(Throwable $e){$pdo->rollBack();flash('error','Product could not be deleted.');}redirect('index.php');
